import{c as r,Q as o,J as n,h as l,k as t,e as i,m as e}from"./chunks/framework.WgZQdPFo.js";const b=JSON.parse('{"title":"Ловушка обрезков: честный раскрой кожи и полезная площадь шкуры","description":"Как правильно делать раскрой кожи и не терять до 30% площади в обрезках. Сводная таблица выхода чепрака и полы, формулы списания MAC и учёт в «ОмниКрафт ЕРП».","frontmatter":{"title":"Ловушка обрезков: честный раскрой кожи и полезная площадь шкуры","description":"Как правильно делать раскрой кожи и не терять до 30% площади в обрезках. Сводная таблица выхода чепрака и полы, формулы списания MAC и учёт в «ОмниКрафт ЕРП».","tags":["Раскрой","Кожевенное дело","Экономика цеха"],"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Ловушка обрезков: честный раскрой кожи и полезная площадь шкуры"}],["meta",{"property":"og:description","content":"Как правильно делать раскрой кожи и не терять до 30% площади в обрезках. Сводная таблица выхода чепрака и полы, формулы списания MAC и учёт в «ОмниКрафт ЕРП»."}],["meta",{"property":"og:url","content":"https://omnicraft-erp.com/ru/articles/lovushka-obrezkov-raskroj-kozhi"}],["meta",{"property":"og:image","content":"https://omnicraft-erp.com/img/ru/calculators/leather-cost-calculator-og.webp"}],["script",{"type":"application/ld+json"},"{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"@graph\\": [\\n    {\\n      \\"@type\\": \\"Article\\",\\n      \\"headline\\": \\"Ловушка обрезков: честный раскрой кожи и полезная площадь шкуры\\",\\n      \\"description\\": \\"Как правильно делать раскрой кожи и не терять до 30% площади в обрезках. Сводная таблица выхода чепрака и полы, формулы списания MAC и учёт в «ОмниКрафт ЕРП».\\",\\n      \\"image\\": [\\n        \\"https://omnicraft-erp.com/img/ru/calculators/leather-cost-calculator-og.webp\\"\\n      ],\\n      \\"inLanguage\\": \\"ru-RU\\",\\n      \\"mainEntityOfPage\\": \\"https://omnicraft-erp.com/ru/articles/lovushka-obrezkov-raskroj-kozhi\\",\\n      \\"datePublished\\": \\"2026-11-04\\",\\n      \\"dateModified\\": \\"2026-11-07\\",\\n      \\"author\\": {\\n        \\"@type\\": \\"Organization\\",\\n        \\"name\\": \\"ОмниКрафт ЕРП\\",\\n        \\"url\\": \\"https://omnicraft-erp.com/ru/\\"\\n      },\\n      \\"publisher\\": {\\n        \\"@type\\": \\"Organization\\",\\n        \\"name\\": \\"ОмниКрафт ЕРП\\",\\n        \\"logo\\": {\\n          \\"@type\\": \\"ImageObject\\",\\n          \\"url\\": \\"https://omnicraft-erp.com/logo.svg\\"\\n        }\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"BreadcrumbList\\",\\n      \\"itemListElement\\": [\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 1,\\n          \\"name\\": \\"Главная\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/ru/\\"\\n        },\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 2,\\n          \\"name\\": \\"Статьи и руководства\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/ru/articles/\\"\\n        },\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 3,\\n          \\"name\\": \\"Раскрой кожи и полезная площадь\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/ru/articles/lovushka-obrezkov-raskroj-kozhi\\"\\n        }\\n      ]\\n    }\\n  ]\\n}\\n"]]},"headers":[],"relativePath":"ru/articles/lovushka-obrezkov-raskroj-kozhi.md","filePath":"ru/articles/lovushka-obrezkov-raskroj-kozhi.md","lastUpdated":1794022768000}'),d={name:"ru/articles/lovushka-obrezkov-raskroj-kozhi.md"},c={class:"interactive-frame-container"};function p(h,a,v,m,g,u){const s=o("OmniCraftFrame");return n(),l("div",null,[a[0]||(a[0]=t('<div class="article-breadcrumb"><a href="/ru/articles/">← Все статьи и руководства</a></div><h1 id="ловушка-обрезков-как-на-самом-деле-делать-раскрои-кожи-и-считать-полезную-площадь" tabindex="-1">Ловушка обрезков: как на самом деле делать раскрой кожи и считать полезную площадь <a class="header-anchor" href="#ловушка-обрезков-как-на-самом-деле-делать-раскрои-кожи-и-считать-полезную-площадь" aria-label="Permalink to &quot;Ловушка обрезков: как на самом деле делать раскрой кожи и считать полезную площадь&quot;">​</a></h1><div class="craft-metaphor-card"><div class="metaphor-header"><div class="metaphor-badge-row"><span class="metaphor-badge">Быстрый ответ</span><span class="metaphor-badge-method">Производственный норматив</span></div><div class="metaphor-title"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="metaphor-icon"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg> «Шкура — не рулон ткани»: почему 100 дм² по паспорту никогда не равны 100 дм² в изделии </div></div><p class="metaphor-story"> Полезная площадь натуральной кожи никогда не равна 100% её паспортного метража. Из-за сложной биологической топографии реальный полезный выход <strong>чепрака составляет 85–90%</strong>, <strong>воротка — 70–75%</strong>, а <strong>полы и пашины — всего 50–60%</strong>. При раскрое крупных деталей сумок технологические выпады достигают 28–32%, при раскрое мелких кардхолдеров — 12–16%. </p><p class="metaphor-story"> Если мастер закладывает в цену только номинальную закупочную цену за дм², он оплачивает 30% обрезков из своего кармана. Фактическая себестоимость считается только через <strong>эффективную цену полезной площади</strong>. </p><div class="metaphor-math-grid"><div class="metaphor-math-step"><div class="step-label">Паспортная площадь</div><div class="step-val">Шкура = <strong>160 дм²</strong></div></div><div class="metaphor-math-op">−</div><div class="metaphor-math-step"><div class="step-label">Потери кроя (30%)</div><div class="step-val">Обрезки = <strong>48 дм²</strong></div></div><div class="metaphor-math-op">=</div><div class="metaphor-math-step highlight-step"><div class="step-label">Реальный выход</div><div class="step-val">Полезно = <strong>112 дм²</strong> (70%)</div></div></div></div><p>Купив полукожу на 180 дм², мастер планирует сшить 10 сумок с расходом по 15 дм² на изделие (итого 150 дм²) и рассчитывает, что оставшиеся 30 дм² пойдут в чистый запас.</p><p>На практике после раскроя шестой сумки целые крупные детали взять больше негде. На верстаке остаются краевые клинья, дряблые пашины и рыхлое брюхо. От 20% до 35% площади шкуры осело в коробке с обрезками.</p><p>Это классическая «ловушка обрезков». Разберём физику шкуры, топографию зон, точные коэффициенты раскроя и математику учёта остатков, чтобы вы перестали дарить клиентам треть своей прибыли.</p><hr><h2 id="_1-анатомическая-топография-почему-шкура-неоднородна" tabindex="-1">1. Анатомическая топография: почему шкура неоднородна <a class="header-anchor" href="#_1-анатомическая-топография-почему-шкура-неоднородна" aria-label="Permalink to &quot;1. Анатомическая топография: почему шкура неоднородна&quot;">​</a></h2><p>В отличие от ткани или листового пластика, натуральная кожа — неоднородный биологический материал с переменной плотностью, толщиной и направлением волокон.</p><p>Шкура крупного рогатого скота делится на четыре базовые анатомические зоны с принципиально разными свойствами:</p><table class="craft-matrix-table"><thead><tr><th style="width:20%;">Зона шкуры</th><th style="width:15%;">Доля площади</th><th style="width:25%;">Структура волокон</th><th style="width:20%;">Растяжимость</th><th style="width:20%;">Назначение в изделии</th></tr></thead><tbody><tr><td><strong>Чепрак (спинная часть)</strong></td><td><strong>45–55%</strong></td><td>Максимальная плотность, плотное сплетение дермы</td><td>Минимальная, стабильная</td><td>Стенки сумок, ремни, нагруженные узлы</td></tr><tr><td><strong>Вороток (шейная часть)</strong></td><td><strong>20–25%</strong></td><td>Высокая прочность, выраженные морщины (складки)</td><td>Тянется поперёк хребта</td><td>Внутренние перегородки, ремешки, мелкие детали</td></tr><tr><td><strong>Пола (брюшная часть)</strong></td><td><strong>15–20%</strong></td><td>Рыхлая клетчатка, тонкий сосочковый слой</td><td>Тянется во всех осях</td><td>Скрытые детали под подкладку, обтачки</td></tr><tr><td><strong>Пашина (паховая часть)</strong></td><td><strong>5–10%</strong></td><td>Крайне рыхлая, тонкая, деформируется как резина</td><td>Нестабильная</td><td>Технологический утиль, прокладки, тесты химии</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Внимание к чепрачной иллюзии</p><p>Начинающий кожевник часто покупает полукожу эконом-сорта (3–4 сорт) по низкой цене за дециметр, надеясь сшить из неё премиальную сумку. Но в низких сортах полезная чепрачная зона изрезана шрамами от колючей проволоки, клеймами и следами оводов. В итоге полезный выход падает до 50%, а эффективная цена полезного дециметра оказывается выше, чем у отборного чепрака 1 сорта.</p></div><hr><h2 id="_2-матрица-кис-реальные-коэффициенты-выхода-площади" tabindex="-1">2. Матрица КИС: реальные коэффициенты выхода площади <a class="header-anchor" href="#_2-матрица-кис-реальные-коэффициенты-выхода-площади" aria-label="Permalink to &quot;2. Матрица КИС: реальные коэффициенты выхода площади&quot;">​</a></h2><p>Чтобы не гадать «хватит ли кожи на тираж», в профессиональном раскрое используется <strong>Коэффициент использования сырья (КИС)</strong>.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Производственный норматив</span><div class="formula-heading">Формула коэффициента использования сырья (КИС)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">КИС</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Чистая площадь деталей по выкройке (дм²)</span></span><span class="math-denom"><span class="math-var">Фактически израсходованная площадь кожи (дм²)</span></span></span></div></div></div><p>Значение КИС напрямую зависит от двух факторов: анатомической зоны и габаритов вырезаемой детали.</p><table class="craft-matrix-table"><thead><tr><th style="width:28%;">Тип изделия / Габариты кроя</th><th style="width:14%;">Чепрак</th><th style="width:14%;">Вороток</th><th style="width:14%;">Пола</th><th style="width:15%;">Средний КИС</th><th style="width:15%;">Потери кроя</th></tr></thead><tbody><tr><td><strong>Крупный крой</strong> (сумки, шоперы, портфели)<br><small style="color:var(--vp-c-text-3);">Детали от 10–25 дм²</small></td><td>0.85–0.88</td><td>0.70–0.75</td><td>0.50–0.55</td><td><strong>0.70</strong></td><td style="color:#ef4444;font-weight:700;">28–32%</td></tr><tr><td><strong>Средний крой</strong> (клатчи, длинные кошельки (лонггеры), папки А4)<br><small style="color:var(--vp-c-text-3);">Детали от 3–8 дм²</small></td><td>0.88–0.92</td><td>0.78–0.82</td><td>0.60–0.65</td><td><strong>0.78</strong></td><td style="color:#f59e0b;font-weight:700;">20–24%</td></tr><tr><td><strong>Мелкий крой</strong> (складные кошельки, картхолдеры, брелоки)<br><small style="color:var(--vp-c-text-3);">Детали до 1–2 дм²</small></td><td>0.92–0.95</td><td>0.85–0.88</td><td>0.70–0.75</td><td><strong>0.86</strong></td><td style="color:#10b981;font-weight:700;">12–16%</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Золотое цеховое правило</p><p>При пошиве сумки закладывайте в расход <strong>нормативный КИС = 0.70</strong>. Это значит, что если по лекалам вам нужно 35 дм² чистой площади, купить и списать со склада придётся минимум:<br><strong>35 ÷ 0.70 = 50 дм² кожи</strong>.</p></div><hr><h2 id="_3-экономика-раскроя-эффективная-цена-дециметра" tabindex="-1">3. Экономика раскроя: эффективная цена дециметра <a class="header-anchor" href="#_3-экономика-раскроя-эффективная-цена-дециметра" aria-label="Permalink to &quot;3. Экономика раскроя: эффективная цена дециметра&quot;">​</a></h2><p>Посмотрим на финансовую разницу между расчётом новичка и честным производственным расчётом.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Финансовая формула</span><div class="formula-heading">Эффективная себестоимость полезного дециметра</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Эффективная цена дм²</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Закупочная стоимость всей шкуры (₽)</span></span><span class="math-denom"><span class="math-var">Фактическая полезная площадь (дм²)</span></span></span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Номинальная цена дм²</span></span><span class="math-denom"><span class="math-var">КИС</span></span></span></div></div></div><h4 id="сравнение-двух-подходов-на-примере-дорожнои-сумки" tabindex="-1">Сравнение двух подходов на примере дорожной сумки: <a class="header-anchor" href="#сравнение-двух-подходов-на-примере-дорожнои-сумки" aria-label="Permalink to &quot;Сравнение двух подходов на примере дорожной сумки:&quot;">​</a></h4><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Параметры закупки:</strong> полукожа 160 дм² по цене 40 ₽/дм² (стоимость шкуры: 6 400 ₽). Чистая площадь сумки по лекалам: 70 дм².</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Расчёт новичка (без КИС):</strong> 70 дм² × 40 ₽ = <strong>2 800 ₽</strong>. Мастер считает, что потратил 2 800 ₽, а остаток на 3 600 ₽ цел и невредим.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Честный производственный расчёт (КИС = 0.68):</strong> 70 ÷ 0.68 = <strong>103 дм²</strong> шкуры занято кроем. В краевые клинья и выпады ушло 33 дм². Реальная себестоимость: 103 × 40 ₽ = <strong>4 120 ₽</strong>.</div></li></ul><div class="warning custom-block"><p class="custom-block-title">Скрытая дыра в кармане</p><p>Разница между расчётами составляет <strong>1 320 рублей чистых убытков на одной сумке</strong>. При объёме 10 сумок в месяц мастер теряет <strong>13 200 ₽ ежемесячно</strong> (158 400 ₽ в год), даже не понимая, куда уходят деньги из кассы.</p></div><hr><h2 id="_4-как-учитывать-обрезки-метод-скользящеи-среднеи-mac" tabindex="-1">4. Как учитывать обрезки: метод скользящей средней (MAC) <a class="header-anchor" href="#_4-как-учитывать-обрезки-метод-скользящеи-среднеи-mac" aria-label="Permalink to &quot;4. Как учитывать обрезки: метод скользящей средней (MAC)&quot;">​</a></h2><p>Что делать с оставшимися 33 дм² обрезков? Оставлять их на балансе склада по полной цене 40 ₽/дм² нельзя: по такой цене их никто не купит, а для крупных деталей они непригодны.</p><p>Профессиональный цеховой стандарт — разделение остатков на две фракции:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Складской стандарт MAC</span><div class="formula-heading">Оприходование деловых остатков с дисконтом ликвидности</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Учётная цена остатка (₽/дм²)</span><span class="math-op">=</span><span class="math-var">Цена закупки шкуры</span><span class="math-op">×</span><span class="math-var">k<sub>ликвидности</sub> (0.4–0.5)</span></div></div></div><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Фракция 1: Технологический утиль (куски &lt; 2 дм²):</strong> списывается в <strong>0 рублей</strong>. Его стоимость целиком закрывается себестоимостью основного изделия (сумки).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Фракция 2: Деловой остаток (куски правильной формы ≥ 2 дм²):</strong> приходуется на склад как вторичное сырьё с дисконтом 0.4–0.5. При базе 40 ₽/дм² остаток ставится на учёт по <strong>18–20 ₽/дм²</strong>. Из него кроятся сверхмаржинальные картхолдеры, брелоки и шлёвки.</div></li></ul><div class="download-banner"><div class="download-info"><div class="download-title">Шаблон расчёта раскроя и себестоимости кожи в Excel</div><div class="download-desc">Формат OpenXML (.xlsx) без макросов. Подходит для Excel, LibreOffice, МойОфис и Google Таблиц.</div></div><div style="display:flex;gap:8px;flex-wrap:wrap;"><a href="/downloads/omnicraft_leather_cost_calculator.xlsx" download="ОмниКрафт_Калькулятор_раскроя_и_себестоимости_кожи.xlsx" class="vp-button brand" data-omni-event="article_download_leather_xlsx"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg><span>Скачать шаблон Excel (.xlsx)</span></a></div></div><hr><h2 id="_5-чек-лист-10-правил-раскроя-за-верстаком" tabindex="-1">5. Чек-лист: 10 правил раскроя за верстаком <a class="header-anchor" href="#_5-чек-лист-10-правил-раскроя-за-верстаком" aria-label="Permalink to &quot;5. Чек-лист: 10 правил раскроя за верстаком&quot;">​</a></h2><p>Чтобы минимизировать потери площади и предотвратить брак, используйте цеховой регламент:</p><ol class="craft-ordered-list"><li><div><strong>Инспекция шкуры перед первым резом:</strong> разметьте серебряным стержнем все пороки (шрамы, овод, клейма). Очертите границы дефектов с припуском 1 см, чтобы они гарантированно не попали на лицевые стенки.</div></li><li><div><strong>Правило хребтовой линии:</strong> продольная ось нагруженных деталей (ремни, ручки сумок, портупеи) должна идти строго параллельно хребту. Поперёк хребта кожа тянется на 15–25% сильнее.</div></li><li><div><strong>Раскрой от крупного к мелкому:</strong> сначала вырезаются самые габаритные детали (фасадные стенки, клапаны, дно). Межлекальные пустоты заполняются деталями карманов, картхолдеров и хлястиков.</div></li><li><div><strong>Угол ножа строго 90°:</strong> завал лезвия дискового или шорного ножа даёт скошенный срез уреза. При склеивании встык дефект проявится ступенькой, которую придётся долго сошлифовывать, теряя геометрию.</div></li><li><div><strong>Плотная подложка без прогиба:</strong> кроите только на качественном самовосстанавливающемся мате или виниловой плите. Мягкая основа прогибается под нажимом, деформируя край лекала.</div></li><li><div><strong>Пола — только на ненагруженные слои:</strong> никогда не кроите из полы наружные детали кошельков или часовые ремешки. Через месяц носки они безвозвратно растянутся и потеряют форму.</div></li><li><div><strong>Учёт толщины на сгибах:</strong> при раскрое деталей с глухим подгибом закладывайте припуск на компенсацию толщины: <code>Δ = 2 × Толщина кожи</code>.</div></li><li><div><strong>Шерфовка края перед сборкой:</strong> если край детали уходит в шов или подгибку, спустите его толщину на 50% ножом для шерфовки или французским торцбилом.</div></li><li><div><strong>Контроль растяжимости парных деталей:</strong> парные боковины сумки кроите строго из одной зоны шкуры (симметрично относительно хребта), иначе одна боковина провиснет раньше другой.</div></li><li><div><strong>Сортировка обрезков сразу в момент кроя:</strong> держите у верстака два раздельных бокса — для делового остатка (≥ 2 дм²) и утиля. Не смешивайте их во избежание складского хаоса.</div></li></ol><hr><h2 id="_6-часто-задаваемые-вопросы-faq" tabindex="-1">6. Часто задаваемые вопросы (FAQ) <a class="header-anchor" href="#_6-часто-задаваемые-вопросы-faq" aria-label="Permalink to &quot;6. Часто задаваемые вопросы (FAQ)&quot;">​</a></h2><div class="craft-faq-accordion"><details class="faq-item"><summary>Как рассчитать расход кожи на сумку, если нет готового лекала?</summary><div class="faq-content"><p> Посчитайте чистую геометрическую площадь основных деталей (длина × ширина прямоугольников стенок, дна и боковин) и прибавьте 15% на ручки, внутренние карманы и подгибы. Полученное число разделите на нормативный КИС = 0.70: </p><div class="formula-hero-card" style="margin:14px 0 8px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Расход кожи (дм²)</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">S<sub>чистая</sub> × 1.15</span></span><span class="math-denom"><span class="math-var">КИС (0.70)</span></span></span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">30 × 1.15</span></span><span class="math-denom"><span class="math-var">0.70</span></span></span><span class="math-op">≈</span><span class="math-var" style="color:var(--vp-c-brand);font-weight:700;">49 дм²</span></div></div></div><p style="margin-top:8px;font-size:0.9rem;color:var(--vp-c-text-2);"> Для сумки чистой площадью 30 дм² необходимо приобрести минимум 49 дм² шкуры с учётом 30% неизбежных технологических потерь кроя. </p></div></details><details class="faq-item"><summary>Почему чепрак стоит дороже полы в 2–3 раза?</summary><div class="faq-content"><p> Чепрак — самая плотная спинная часть шкуры с переплетёнными коллагеновыми волокнами. У него практически нет растяжения, однородная толщина и высокая износостойкость. Пола (брюшная часть) рыхлая, легко тянется и деформируется от влаги. </p></div></details><details class="faq-item"><summary>Можно ли пускать полу на пошив кошельков?</summary><div class="faq-content"><p> Только на скрытые внутренние перегородки под текстильную подкладку. На наружные стенки и открытые карманы карт пола не подходит: она рыхлая и быстро потеряет форму при ежедневном извлечении карт. </p></div></details><details class="faq-item"><summary>Как заложить обрезки в цену изделия?</summary><div class="faq-content"><p> Делите чистую площадь изделия по выкройке на коэффициент КИС (для сумок — 0.68–0.70, для мелкой галантереи — 0.85). Полученный метраж умножайте на закупочную цену за дм²: </p><div class="formula-hero-card" style="margin:14px 0 8px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Затраты на кожу (₽)</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">S<sub>выкройки</sub> (дм²)</span></span><span class="math-denom"><span class="math-var">КИС</span></span></span><span class="math-op">×</span><span class="math-var">Цена закупки (₽/дм²)</span></div></div></div><p style="margin-top:8px;font-size:0.9rem;color:var(--vp-c-text-2);"> Либо используйте эквивалентный расчёт через эффективную себестоимость полезного дециметра: <code>S<sub>выкройки</sub> × (Цена закупки ÷ КИС)</code>. </p></div></details></div><hr><h2 id="_7-автоматизация-в-«омникрафт-ерп»-учет-без-блокнота" tabindex="-1">7. Автоматизация в «ОмниКрафт ЕРП»: учёт без блокнота <a class="header-anchor" href="#_7-автоматизация-в-«омникрафт-ерп»-учет-без-блокнота" aria-label="Permalink to &quot;7. Автоматизация в «ОмниКрафт ЕРП»: учёт без блокнота&quot;">​</a></h2><p>Считать коэффициенты раскроя и отслеживать деловые остатки вручную для каждого изделия в блокноте или таблицах — верный способ запутаться в десятках шкур и потерять контроль над маржинальностью.</p><p>Когда в мастерской одновременно находятся 5 видов кож разной цены за дециметр, а обрезки переходят из заказа в заказ, ручной учёт отнимает часы времени.</p><p>Профессиональная система связывает раскрой, складской учёт сырья и списание себестоимости в единый контур:</p>',45)),i("div",c,[e(s,{screen:"calculator",slider:"",zoomable:"",lang:"ru",caption:"Интерфейс калькулятора партии в «ОмниКрафт ЕРП»: спецификация партии, автоматический расчёт расхода кожи с поправкой на КИС и списание деловых остатков"})]),a[1]||(a[1]=t('<p>В программе <strong>«ОмниКрафт ЕРП»</strong> калькулятор смет автоматически рассчитывает полезный выход сырья по коэффициенту КИС, списывает деловые остатки на склад вторичных материалов по методу MAC и фиксирует чистую маржинальность каждого заказа.</p><div class="cta-grid"><div class="cta-card featured-cta"><div><div class="cta-card-badge brand-badge">Программа для мастерской</div><h3>ОмниКрафт ЕРП для кожевников</h3><p> Автоматический расчёт коэффициента использования сырья (КИС), партионный учёт деловых остатков по методу MAC и точный норма-час мастера. </p></div><a href="/ru/docs/getting-started" class="vp-button brand cta-icon-btn"><span>Попробовать бесплатно</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div><div class="cta-card"><div><div class="cta-card-badge">Бесплатный инструмент</div><h3>Калькулятор себестоимости кожи</h3><p> Рассчитайте себестоимость изделия онлайн с учётом полезной площади, химии, амортизации и скачайте шаблон в Excel. </p></div><a href="/ru/calculators/leather-cost-calculator" class="vp-button alt cta-icon-btn"><span>Открыть калькулятор</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div></div><hr><h2 id="связанные-статьи-производственного-кластера" tabindex="-1">Связанные статьи производственного кластера <a class="header-anchor" href="#связанные-статьи-производственного-кластера" aria-label="Permalink to &quot;Связанные статьи производственного кластера&quot;">​</a></h2><ul><li><a href="/ru/calculators/leather-cost-calculator">Калькулятор себестоимости изделий из кожи онлайн</a> — интерактивный расчёт расхода шкуры, химии уреза, фурнитуры и нормы-часа мастера.</li><li><a href="/ru/articles/pricing-and-margins">Ценообразование, наценка и маржа: как рассчитать цену изделия и не работать в минус</a> — флагманское руководство по формулам безубыточности и торговой наценке.</li><li><a href="/ru/articles/cost-calculation-software">Программы для расчёта себестоимости: почему Excel и 1С не подходят малым мастерским</a> — архитектурное сравнение учётных систем для штучного производства.</li><li><a href="/ru/calculators/product-cost-calculator">Универсальный онлайн-калькулятор себестоимости продукции</a> — базовый расчёт единицы товара с экспортом сметы в файл Excel (.xlsx).</li><li><a href="/ru/calculators/">Каталог онлайн-калькуляторов себестоимости «ОмниКрафт ЕРП»</a> — отраслевые инструменты расчёта смет для 7 производственных направлений.</li></ul>',5))])}const y=r(d,[["render",p]]);export{b as __pageData,y as default};
